# -*- coding: utf-8 -*-
OT_DAYS_6 = [
{"day":120,"book":"Proverbs","ref":"Proverbs 1-5","title":"The Beginning of Wisdom",
 "chapters":[
  ("Prov 1","Introduces Proverbs' purpose -- gaining wisdom, discipline, and understanding -- personifying wisdom as a public voice calling out to the simple to turn from folly."),
  ("Prov 2","Describes the rewards of pursuing wisdom like hidden treasure, protecting from both evil men and immoral women."),
  ("Prov 3","Contains some of Proverbs' most memorized verses, urging trust in the LORD 'with all your heart' rather than leaning on your own understanding."),
  ("Prov 4","A father's earnest appeal to his son to guard wisdom above all else, since 'from it flow the springs of life.'"),
  ("Prov 5","Warns specifically against sexual immorality and adultery, commending instead faithful delight in one's own spouse."),
 ],
 "themes":["Wisdom begins with reverence for God, not mere intelligence or cleverness.","A father's earnest appeal for his child to value wisdom reflects the seriousness of character formation."],
 "expositor":("waltke","Waltke, whose extensive Proverbs commentary remains a standard reference, observed that Proverbs 1:7's declaration -- 'the fear of the LORD is the beginning of knowledge' -- functions as the interpretive key for understanding every practical proverb that follows in the rest of the book."),
 "reflect":"How does reverence for God currently shape your everyday, practical decision-making, not just your beliefs?"},

{"day":121,"book":"Proverbs","ref":"Proverbs 6-10","title":"Wisdom's Public Call",
 "chapters":[
  ("Prov 6","Warns against financial foolishness, laziness (using the ant as an example), and further consequences of adultery."),
  ("Prov 7","A vivid narrative warning against the seductive persuasion of the immoral woman, portraying the naive young man's path toward destruction."),
  ("Prov 8","Wisdom is personified as calling out publicly, present with God even at creation, offering riches far greater than silver or gold."),
  ("Prov 9","Contrasts wisdom's invitation to a life-giving feast with folly's invitation to a deadly, secret one."),
  ("Prov 10","Begins Solomon's collection of short, independent proverbs, contrasting wise and foolish, righteous and wicked, in areas like speech, work, and wealth."),
 ],
 "themes":["Wisdom's public, urgent invitation contrasts with folly's secretive, seductive appeal.","Even ancient wisdom literature recognized laziness and poor financial habits as serious character issues."],
 "expositor":("kidner","Kidner observed that Proverbs 8's personification of wisdom as present with God 'at the first, before the beginning of the earth' gives wisdom a cosmic significance far beyond mere practical advice -- it reflects something of God's own character woven into creation itself."),
 "reflect":"Which invitation are you more often responding to lately -- wisdom's public call to a life-giving path, or folly's more subtle, private appeal?"},

{"day":122,"book":"Proverbs","ref":"Proverbs 11-15","title":"Wise and Foolish, Righteous and Wicked",
 "chapters":[
  ("Prov 11-15","This section continues Solomon's collected proverbs, covering themes such as honest business dealings, humility versus pride, the power of a gentle answer to turn away wrath, the value of good counsel, and the far-reaching effects of both wise and foolish speech."),
 ],
 "themes":["Wise and foolish patterns of speech, work, and character are contrasted repeatedly throughout this collection.","A gentle answer's power to defuse conflict is a small, practical wisdom with large relational impact."],
 "expositor":("waltke","Waltke noted that Proverbs' repeated short, contrasting couplets -- the wise versus the fool, the righteous versus the wicked -- are meant to be read slowly and reflected on individually, not rushed through as a single narrative."),
 "reflect":"Which single proverb from this section, if actually applied this week, would most improve one of your relationships?"},

{"day":123,"book":"Proverbs","ref":"Proverbs 16-20","title":"God's Sovereignty, A Good Name",
 "chapters":[
  ("Prov 16-20","Continues collected proverbs on themes including trusting God's sovereign plans over human schemes, the value of a good name over riches, the danger of pride before a fall, and the importance of diligent, honest work."),
 ],
 "themes":["Human plans remain subject to God's ultimate sovereign purposes.","A good reputation, built over time through integrity, is more valuable than any amount of wealth."],
 "expositor":("mcgee","McGee often highlighted Proverbs 16:9 -- 'in their hearts humans plan their course, but the LORD establishes their steps' -- as a helpful corrective to both reckless planning and anxious over-planning, since ultimate direction remains God's to establish."),
 "reflect":"Where might you be either over-relying on your own planning, or neglecting to plan at all, rather than holding your plans with open hands before God?"},

{"day":124,"book":"Proverbs","ref":"Proverbs 21-25","title":"The King's Heart, Generosity Toward the Poor",
 "chapters":[
  ("Prov 21-25","Continues collected proverbs addressing the king's heart in God's hand, the danger of quarreling and gossip, generosity toward the poor, disciplining children, and practical wisdom for various relationships and circumstances."),
 ],
 "themes":["Even a king's heart remains fully within God's sovereign control, not beyond it.","Practical generosity toward the poor is treated as a matter of genuine wisdom, not mere sentiment."],
 "expositor":("waltke","Waltke pointed out that Proverbs 21:1's claim that even 'the king's heart is like a stream of water in the hand of the LORD' offered genuine comfort to ancient readers living under unpredictable, sometimes harsh, rulers -- ultimate authority remained God's, regardless of who sat on the throne."),
 "reflect":"Is there a situation involving someone else's authority over you where trusting God's ultimate sovereignty could bring genuine peace?"},

{"day":125,"book":"Proverbs","ref":"Proverbs 26-28","title":"Honest Friendship, Unstable Wealth",
 "chapters":[
  ("Prov 26","Warns against honoring fools and describes the self-defeating nature of laziness and gossip."),
  ("Prov 27","Uses vivid, memorable imagery -- iron sharpening iron, a faithful friend's wounds -- to describe genuine friendship and self-awareness."),
  ("Prov 28","Contrasts the security of the righteous with the instability of the wicked, especially regarding wealth gained unjustly."),
 ],
 "themes":["Genuine friendship sometimes requires the discomfort of honest correction, not just comfortable affirmation.","Ill-gotten wealth ultimately proves unstable compared to wealth gained through integrity."],
 "expositor":("kidner","Kidner noted that Proverbs 27:6's memorable line -- 'wounds from a friend can be trusted, but an enemy multiplies kisses' -- reframes painful honesty from a valued friend as a genuine gift, compared to the false comfort of flattery."),
 "reflect":"Do you have a friend whose honest 'wounds' you actually trust, the way Proverbs 27:6 describes, rather than only surrounding yourself with flattery?"},

{"day":126,"book":"Proverbs","ref":"Proverbs 29-31","title":"Humility's Limits, A Life of Noble Character",
 "chapters":[
  ("Prov 29","Continues warnings about pride, anger, and the value of godly leadership."),
  ("Prov 30","Records Agur's humble sayings about the limits of human knowledge and dependence on God."),
  ("Prov 31","Closes with King Lemuel's teaching from his mother and the famous acrostic poem praising 'the wife of noble character.'"),
 ],
 "themes":["Genuine humility includes recognizing the real limits of human knowledge and understanding.","Proverbs closes by praising practical, industrious, God-fearing character as true excellence, not mere outward beauty."],
 "expositor":("waltke","Waltke observed that Proverbs 31's closing poem praising the 'wife of noble character' celebrates practical competence, business acumen, and generosity toward the poor as genuine wisdom in action -- not a narrow domestic ideal, but a full, active life lived skillfully before God."),
 "reflect":"What would it look like for you to pursue the kind of practical, active, God-fearing excellence Proverbs 31 describes, in your own specific life circumstances?"},

{"day":127,"book":"Ecclesiastes","ref":"Ecclesiastes 1-4","title":"Meaningless Under the Sun",
 "chapters":[
  ("Eccl 1","The Teacher opens by declaring everything 'meaningless' under the sun, observing that human striving and even wisdom itself cannot secure lasting satisfaction."),
  ("Eccl 2","The Teacher tests pleasure, achievement, and wealth to their fullest extent, finding all of it ultimately unable to provide lasting meaning."),
  ("Eccl 3","Famously describes 'a time for everything,' acknowledging life's rhythms while noting that God 'has planted eternity in the human heart,' creating a longing nothing temporal can satisfy."),
  ("Eccl 4","Observes further examples of life's apparent futility -- oppression, isolated toil, envy-driven achievement -- while commending the practical value of companionship."),
 ],
 "themes":["Pursuing meaning through achievement or pleasure alone, apart from God, ultimately disappoints.","God has placed a longing for eternity within every human heart that nothing temporal can satisfy."],
 "expositor":("kaiser","Kaiser observed that Ecclesiastes' repeated phrase 'under the sun' is the key to understanding the whole book -- the Teacher isn't denying meaning exists, but exposing how empty life becomes when evaluated only by what's visible from a purely earthly, God-excluded vantage point."),
 "reflect":"Is there an area of your life you've been evaluating only 'under the sun' -- by purely earthly measures -- rather than including God's larger perspective?"},

{"day":128,"book":"Ecclesiastes","ref":"Ecclesiastes 5-8","title":"Wealth's Limits, Wisdom's Value",
 "chapters":[
  ("Eccl 5","Warns against careless words before God and empty religious vows, and observes that wealth itself, however great, never fully satisfies."),
  ("Eccl 6","Continues observing that possessions and long life mean little without the capacity to actually enjoy them as God's gift."),
  ("Eccl 7","Offers practical wisdom contrasting the value of a good reputation, patience, and wisdom against foolish pursuits of pleasure or excessive analysis."),
  ("Eccl 8","Reflects on the mystery of God's ways, acknowledging that humans cannot fully grasp why the wicked sometimes prosper and the righteous sometimes suffer."),
 ],
 "themes":["Wealth and possessions, however abundant, cannot themselves provide the capacity to enjoy life.","Human wisdom has real, practical value, even while acknowledging its limits in fully explaining life's mysteries."],
 "expositor":("kidner","Analysis in the tradition of Kidner's wisdom-literature scholarship notes that Ecclesiastes 5-6 presents the ability to actually enjoy what we have as itself a distinct gift from God, separate from merely possessing it -- explaining why some wealthy people remain unsatisfied while some with less genuinely flourish."),
 "reflect":"Do you currently have the capacity to enjoy what God has already given you, or are you waiting for more before you'll allow yourself to be content?"},

{"day":129,"book":"Ecclesiastes","ref":"Ecclesiastes 9-12","title":"Fear God and Keep His Commandments",
 "chapters":[
  ("Eccl 9","Observes that death comes to all regardless of righteousness or wickedness, commending instead the wholehearted enjoyment of ordinary life as God's gift in the time we're given."),
  ("Eccl 10","Offers various practical proverbs on wisdom and folly, particularly regarding leadership and speech."),
  ("Eccl 11","Encourages venturing generosity and effort despite life's genuine uncertainties, since we cannot know which efforts will ultimately succeed."),
  ("Eccl 12","Closes with a poetic meditation on aging and death, before delivering the book's final conclusion: 'fear God and keep his commandments, for this is the duty of all mankind.'"),
 ],
 "themes":["Life's brevity and uncertainty should prompt wholehearted engagement, not paralysis or despair.","The whole book's conclusion redirects all its searching questions toward simple reverence and obedience to God."],
 "expositor":("kaiser","Kaiser pointed out that Ecclesiastes' famous concluding verse functions as the resolution to twelve chapters of searching, showing that simple, obedient reverence for God, not additional achievement or analysis, is what ultimately answers the book's questions."),
 "reflect":"After all of Ecclesiastes' searching, its answer is simple reverence and obedience. Is there a way you've been overcomplicating what genuine faithfulness to God actually requires?"},

{"day":130,"book":"Song of Songs","ref":"Song of Songs 1-4","title":"A Love Poem Begins",
 "chapters":[
  ("Song 1","The bride and groom exchange expressions of mutual attraction and admiration, opening the book's celebration of romantic love."),
  ("Song 2","The lovers continue their poetic exchange, with the well-known image of the beloved as 'a lily among thorns' and the famous refrain not to 'arouse or awaken love' before its proper time."),
  ("Song 3","The bride dreams of anxiously searching for her beloved, and the wedding procession of King Solomon is described in celebratory detail."),
  ("Song 4","The groom extensively praises his bride's beauty, and the couple's love reaches full physical and relational union."),
 ],
 "themes":["Romantic love, including physical attraction, is treated in Scripture as good and worth celebrating within marriage.","Love has its proper timing and shouldn't be rushed or forced prematurely."],
 "expositor":("waltke","Waltke observed that Song of Songs' unembarrassed celebration of romantic and physical love between husband and wife stands as Scripture's own corrective against any impulse to view sexuality within marriage as merely tolerated rather than genuinely good."),
 "reflect":"How does viewing married love as something Scripture actively celebrates, not merely permits, shape your own view of that gift?"},

{"day":131,"book":"Song of Songs","ref":"Song of Songs 5-8","title":"Love as Strong as Death",
 "chapters":[
  ("Song 5","The bride dreams of a troubling separation from her groom, prompting an extended description of his admirable qualities to her friends."),
  ("Song 6","The groom responds with continued praise for his bride's unique beauty, comparing her favorably to any other."),
  ("Song 7","The groom's admiration continues in vivid poetic detail, and the bride confidently invites him to enjoy their love together."),
  ("Song 8","The book closes with reflections on love's exclusive, unquenchable strength -- 'many waters cannot quench love' -- and the bride's confident, secure identity in her beloved's love."),
 ],
 "themes":["Genuine love includes seasons of longing, searching, and even temporary separation.","Secure identity in being genuinely loved provides a stability nothing else can offer."],
 "expositor":("kidner","Analysis in the tradition of Kidner's approach to Song of Songs 8 notes that its closing declaration -- 'love is as strong as death... many waters cannot quench love' -- presents committed love as one of the most powerful forces described anywhere in Scripture, worth protecting and cultivating deliberately."),
 "reflect":"What would it look like to more deliberately protect and cultivate a significant love relationship in your own life this week?"},

{"day":132,"book":"Isaiah","ref":"Isaiah 1-6","title":"Holy, Holy, Holy",
 "chapters":[
  ("Isa 1","Isaiah opens with God's charge against Judah's rebellion, exposing how their outward religious ritual has become disconnected from genuine justice and righteousness."),
  ("Isa 2","Isaiah envisions a future day when the nations will stream to God's mountain for instruction and peace, contrasted with a present day of judgment on pride."),
  ("Isa 3-4","Judah's coming judgment is described in detail, particularly the arrogance of its leaders and daughters, followed by a promise of a future purified, restored remnant."),
  ("Isa 5","A vineyard parable illustrates God's disappointed expectation over Judah's failure to produce justice and righteousness despite His careful cultivation."),
  ("Isa 6","Isaiah's dramatic vision of God's holiness in the temple ('holy, holy, holy') leads to his own confession of sin, cleansing, and commissioning as a prophet."),
 ],
 "themes":["Outward religious ritual disconnected from genuine justice provokes God's strong displeasure.","Genuine encounter with God's holiness leads first to conviction, then to cleansing and calling."],
 "expositor":("motyer","Motyer, the leading evangelical authority on Isaiah, observed that Isaiah's temple vision in chapter 6 -- confronting God's holiness before receiving his prophetic call -- establishes the pattern for all genuine ministry: cleansing must precede commissioning."),
 "reflect":"Isaiah's vision led first to conviction before commissioning. Is there an area where you've sought calling or purpose while skipping over needed conviction?"},

{"day":133,"book":"Isaiah","ref":"Isaiah 7-12","title":"Immanuel, and a Coming Ruler of Peace",
 "chapters":[
  ("Isa 7","Facing a political crisis, King Ahaz refuses to trust God, and Isaiah delivers the famous Immanuel prophecy of a virgin-born son as a sign."),
  ("Isa 8","Isaiah continues warning of coming judgment through Assyria, while urging trust in God rather than fear of political powers."),
  ("Isa 9","One of Isaiah's most celebrated messianic prophecies describes a coming child who will be called 'Wonderful Counselor, Mighty God, Everlasting Father, Prince of Peace.'"),
  ("Isa 10","Isaiah pronounces judgment on proud, self-glorifying Assyria, even though God had used it as His instrument of discipline."),
  ("Isa 11","Isaiah describes a coming righteous ruler from David's line, under whose reign even creation itself will experience remarkable peace."),
  ("Isa 12","A short psalm of praise and trust closes this section, celebrating God as salvation and strength."),
 ],
 "themes":["God's promises of a coming Messiah were given centuries in advance, with striking specificity.","Trusting God rather than political alliances remains a live choice in every generation of crisis."],
 "expositor":("motyer","Motyer noted that Isaiah 9's list of messianic titles makes an audacious claim of divine identity for the coming child centuries before Christ's birth, a claim the New Testament directly affirms is fulfilled in Jesus."),
 "reflect":"Is there a current pressure to trust a human solution rather than God, similar to what Ahaz faced in chapter 7?"},

{"day":134,"book":"Isaiah","ref":"Isaiah 13-18","title":"Judgment on the Nations",
 "chapters":[
  ("Isa 13-14","Oracles of judgment against Babylon include a taunt against its arrogant king, a passage historically applied to the fall of a proud, self-exalting power."),
  ("Isa 15-16","Oracles of judgment and lament are pronounced against Moab, a nation historically hostile yet related to Israel."),
  ("Isa 17-18","Oracles address judgment against Damascus (Aram) and a distant African nation, showing God's sovereignty extends over every nation, not Judah alone."),
 ],
 "themes":["God's sovereignty and justice extend over every nation, not Israel and Judah alone.","Pride and self-exaltation, wherever they appear, ultimately invite God's humbling judgment."],
 "expositor":("motyer","Motyer observed that Isaiah's oracles against the nations serve a pastoral purpose for Judah as much as a warning to foreign powers -- proving that the God who judges Babylon and Moab is also fully capable of both judging and protecting His own people."),
 "reflect":"How does knowing God's sovereignty extends over every nation and situation, not just your own personal concerns, shape your view of current world events?"},

{"day":135,"book":"Isaiah","ref":"Isaiah 19-24","title":"Surprising Grace for Enemies, Universal Judgment",
 "chapters":[
  ("Isa 19-20","Oracles concerning Egypt describe both judgment and, remarkably, a future day when Egypt too will know and worship the LORD alongside Israel and Assyria."),
  ("Isa 21-23","Further oracles pronounce judgment on Babylon, Edom, Arabia, Jerusalem itself, and the wealthy trading city of Tyre."),
  ("Isa 24","A broader vision describes a coming judgment upon the whole earth, moving beyond specific nations to a universal reckoning."),
 ],
 "themes":["God's future plans surprisingly include even historic enemy nations coming to know and worship Him.","A day of universal reckoning awaits the whole earth, not merely specific rebellious nations."],
 "expositor":("motyer","Motyer highlighted Isaiah 19's remarkable prophecy that Egypt and Assyria -- Israel's historic oppressors -- would one day worship the LORD alongside Israel as an early, striking anticipation of the gospel's later reach to all nations."),
 "reflect":"Is there a group of people you'd consider unlikely candidates for God's grace, the way Egypt and Assyria would have seemed to Isaiah's original audience?"},

{"day":136,"book":"Isaiah","ref":"Isaiah 25-30","title":"Victory Over Death, A Cornerstone in Zion",
 "chapters":[
  ("Isa 25-26","Celebrate God's future victory over death itself ('he will swallow up death forever') and a song of trust in the God who keeps in perfect peace those whose minds are fixed on Him."),
  ("Isa 27","Describes God's ultimate defeat of the forces of chaos and evil and Israel's eventual restoration."),
  ("Isa 28-29","Pronounce woes against Israel's and Judah's drunken, complacent leaders, while promising a coming 'cornerstone' laid in Zion."),
  ("Isa 30","Warns against seeking security through alliance with Egypt rather than trusting God, while promising future restoration for those who wait on Him."),
 ],
 "themes":["God's ultimate victory over death itself gives believers hope beyond any present circumstance.","Trusting God rather than human alliances remains the central choice facing God's people under threat."],
 "expositor":("motyer","Motyer noted that Isaiah 25:8's promise that God 'will swallow up death forever' is quoted directly by Paul in 1 Corinthians 15, showing this Old Testament hope finds its full historical fulfillment in Christ's resurrection."),
 "reflect":"How does the promise that God will one day swallow up death forever change how you currently face fear of death or loss?"},

{"day":137,"book":"Isaiah","ref":"Isaiah 31-36","title":"A Vision of Restoration",
 "chapters":[
  ("Isa 31-32","Continue warning against trusting Egypt's military strength over God, while envisioning a future righteous kingdom of justice and peace."),
  ("Isa 33-35","Describe both coming judgment and a strikingly beautiful vision of restoration, where 'the desert will rejoice and blossom' and the blind will see, the deaf will hear, and the lame will leap."),
  ("Isa 36","Assyria's field commander mocks Judah and pressures Jerusalem to surrender during Sennacherib's siege, setting up the following historical narrative."),
 ],
 "themes":["Trusting worldly strength over God consistently proves to be a costly mistake throughout Scripture.","God's promised future restoration includes vivid healing and joy, not merely the absence of judgment."],
 "expositor":("motyer","Motyer observed that Isaiah 35's vision of the blind seeing, the deaf hearing, and the lame leaping directly anticipates the very miracles Jesus performed, which He himself cited as evidence of His messianic identity when John the Baptist's disciples questioned him (Matthew 11:4-5)."),
 "reflect":"Isaiah 35 envisions restoration going beyond merely fixing problems to genuine flourishing and joy. Where in your own life are you hoping for more than just relief -- for genuine flourishing?"},

{"day":138,"book":"Isaiah","ref":"Isaiah 37-42","title":"Deliverance, Then Comfort",
 "chapters":[
  ("Isa 37","King Hezekiah takes Assyria's threatening letter directly to the temple in prayer, and God miraculously destroys the besieging Assyrian army overnight."),
  ("Isa 38-39","Hezekiah's recovery from illness and his later, prideful display of Judah's wealth to Babylonian envoys are recorded, foreshadowing future exile."),
  ("Isa 40","A dramatic shift begins, opening with God's tender comfort for His people ('comfort, comfort my people') and celebrating His unmatched, sovereign greatness compared to any idol."),
  ("Isa 41","God reassures His people not to fear, since He, the sovereign Lord of history, will strengthen and help them."),
  ("Isa 42","The first of Isaiah's 'Servant Songs' introduces a coming Servant who will bring justice gently, without breaking a bruised reed, ultimately understood as a picture of Christ."),
 ],
 "themes":["Bringing a threatening situation directly to God in prayer, as Hezekiah did, can precede remarkable deliverance.","God's comfort for His discouraged people flows from His unmatched, sovereign greatness over any rival power."],
 "expositor":("motyer","Motyer noted that Isaiah 40's opening command to 'comfort my people' marks a decisive shift in the book's tone, moving from warning to consolation, precisely because Israel's punishment, though real, would not be God's final word."),
 "reflect":"Is there an area where you need to hear God's comfort, not further warning, at this point in your own journey?"},

{"day":139,"book":"Isaiah","ref":"Isaiah 43-48","title":"Naming Cyrus, Mocking Idols",
 "chapters":[
  ("Isa 43","God reassures Israel of His redeeming love, declaring them 'precious and honored' in His sight despite their failures."),
  ("Isa 44-45","God mocks the folly of idol-making and identifies Cyrus by name over a century before his birth as the ruler who would enable Israel's return from exile."),
  ("Isa 46-47","Contrast the true, sovereign God who declares 'the end from the beginning' with the coming humiliation of proud, idolatrous Babylon."),
  ("Isa 48","God calls Israel to learn from their past stubbornness and to genuinely heed His voice going forward."),
 ],
 "themes":["God's specific, centuries-advance naming of Cyrus demonstrates His sovereignty over history in remarkable detail.","Idol worship is repeatedly mocked in Scripture as fundamentally irrational, not merely wrong."],
 "expositor":("motyer","Motyer observed that God naming Cyrus by name in Isaiah 44-45, more than a century before his birth, functions as one of Scripture's clearest, most specific evidences of predictive prophecy, directly challenging skeptical claims about the book's dating."),
 "reflect":"How does God's precise, long-range sovereignty over history, as shown in the Cyrus prophecy, affect your confidence in His control over your own uncertain future?"},

{"day":140,"book":"Isaiah","ref":"Isaiah 49-54","title":"Pierced for Our Transgressions",
 "chapters":[
  ("Isa 49","The second Servant Song describes the Servant's mission to restore Israel and become 'a light for the Gentiles,' extending salvation to the ends of the earth."),
  ("Isa 50","The third Servant Song describes the Servant's humble, willing endurance of suffering and shame in obedience to God's mission."),
  ("Isa 51-52","God comforts His people with promises of restoration, and Isaiah 52 closes with a description of the Servant's exaltation following prior disfigurement and suffering."),
  ("Isa 53","The climactic fourth Servant Song describes the Servant's substitutionary suffering in unmistakable detail -- 'he was pierced for our transgressions' -- the clearest Old Testament portrait of Christ's atoning death."),
  ("Isa 54","God promises Israel a future of restored relationship, likened to a renewed marriage covenant, secured by His unfailing love."),
 ],
 "themes":["Isaiah 53's detailed prophecy of substitutionary suffering is the clearest Old Testament portrait of Christ's atoning death.","God's mission always extended beyond Israel alone, toward becoming 'a light for the Gentiles.'"],
 "expositor":("motyer","Motyer called Isaiah 53 the mountain peak of Old Testament prophecy, noting its startlingly precise description of a suffering, substitutionary death for others' sin, written roughly seven centuries before crucifixion existed as a Roman punishment."),
 "reflect":"Isaiah 53:5 says the Servant was pierced for our transgressions. How does dwelling on the specificity of this ancient prophecy strengthen your confidence in the gospel's historical foundation?"},

{"day":141,"book":"Isaiah","ref":"Isaiah 55-60","title":"A Free Invitation, True Fasting",
 "chapters":[
  ("Isa 55","God extends a free, gracious invitation to 'all who are thirsty,' promising that His word will not return empty but will accomplish His purposes."),
  ("Isa 56-57","God promises inclusion for foreigners and eunuchs who hold fast to His covenant, while rebuking Israel's continued idolatry and complacent leadership."),
  ("Isa 58","Isaiah confronts hollow religious fasting disconnected from genuine justice, defining true fasting as sharing bread with the hungry and freeing the oppressed."),
  ("Isa 59","Isaiah diagnoses the root of Israel's separation from God as their own sin, while describing God's own arm bringing salvation when no human intercessor could be found."),
  ("Isa 60","A glorious vision describes nations streaming to Jerusalem's future light, drawn by the glory of the LORD risen upon her."),
 ],
 "themes":["God's invitation to salvation is free and gracious, extended to all who are genuinely thirsty.","True religious devotion is inseparable from practical justice toward the hungry and oppressed."],
 "expositor":("motyer","Motyer observed that Isaiah 58's redefinition of true fasting -- sharing bread with the hungry, freeing the oppressed -- refuses to let religious devotion remain a private, ritual-only matter disconnected from how we actually treat vulnerable people."),
 "reflect":"Is there a way your own spiritual disciplines have become disconnected from practical care for those in need around you?"},

{"day":142,"book":"Isaiah","ref":"Isaiah 61-66","title":"New Heavens and a New Earth",
 "chapters":[
  ("Isa 61","Describes the Spirit-anointed Servant's mission to proclaim good news to the poor, freedom for captives, and comfort for those who mourn -- the very passage Jesus read and claimed as fulfilled in Luke 4."),
  ("Isa 62-63","Describe God's passionate, marriage-like commitment to Zion's restoration, and a vivid depiction of God's judgment portrayed as treading a winepress alone."),
  ("Isa 64","A prayer pleading for God to powerfully intervene, acknowledging Israel's persistent sinfulness even while calling on His fatherly mercy."),
  ("Isa 65-66","Close the book with the sweeping vision of 'new heavens and a new earth,' where former troubles are forgotten and God's people finally experience complete, lasting joy."),
 ],
 "themes":["Jesus explicitly claimed Isaiah 61's Spirit-anointed mission as His own at the start of His ministry.","Isaiah's closing vision of 'new heavens and a new earth' anticipates Revelation's identical, climactic hope."],
 "expositor":("motyer","Motyer noted that Jesus' choice to read Isaiah 61 in the Nazareth synagogue and declare it fulfilled 'today' (Luke 4:16-21) shows Jesus Himself identifying this prophecy as the explicit mission statement for His entire ministry."),
 "reflect":"Isaiah 61's mission -- good news to the poor, freedom for captives, comfort for mourners -- became Jesus' own mission statement. How might it also shape yours as His follower?"},
]
